<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{platformApi}from'../services/platform'
const rows=ref<any[]>([]),loading=ref(true),error=ref(''),notice=ref(''),show=ref(false),saving=ref(false),editingId=ref<number|null>(null),rolloutFeature=ref(''),rollouts=ref<any[]>([]),editingRollout=ref<number|null>(null)
const emptyForm=()=>({feature_code:'',feature_name:'',category:'enterprise',description:'',client_type:'all',default_enabled:false,status:'internal',minimum_client_version:'',schemaText:'{}'});const form=reactive<any>(emptyForm())
const emptyRollout=()=>({rollout_type:'percentage',percentage:10,organizationText:'',deviceText:'',minimum_version:'',starts_at:'',ends_at:'',status:'active'});const rollout=reactive<any>(emptyRollout())
async function load(){loading.value=true;error.value='';try{rows.value=(await platformApi.definitions()).items}catch(e:any){error.value=e.message}finally{loading.value=false}}
function edit(row?:any){editingId.value=row?.id||null;Object.assign(form,row?{...row,schemaText:JSON.stringify(row.config_schema||{},null,2)}:emptyForm());show.value=true}
async function saveFeature(){let schema;try{schema=JSON.parse(form.schemaText||'{}')}catch{error.value='Schema 必须是有效 JSON';return}if(editingId.value&&form.status==='deprecated'&&!window.confirm('废弃功能会阻止所有套餐、企业和设备覆盖，确认继续吗？'))return;saving.value=true;try{await platformApi.saveDefinition(editingId.value,{feature_code:form.feature_code,feature_name:form.feature_name,category:form.category,description:form.description,client_type:form.client_type,default_enabled:form.default_enabled,status:form.status,minimum_client_version:form.minimum_client_version,config_schema:schema});show.value=false;notice.value=`功能“${form.feature_name}”已${editingId.value?'更新':'创建'}，全局配置版本已刷新。`;await load()}catch(e:any){error.value=`保存失败：${e.message}`}finally{saving.value=false}}
async function selectFeature(){editingRollout.value=null;Object.assign(rollout,emptyRollout());rollouts.value=rolloutFeature.value?(await platformApi.rollouts(rolloutFeature.value)).items:[]}
function editRollout(row:any){editingRollout.value=row.id;Object.assign(rollout,{...row,organizationText:(row.organization_ids||[]).join(','),deviceText:(row.device_ids||[]).join(','),starts_at:row.starts_at?String(row.starts_at).slice(0,16):'',ends_at:row.ends_at?String(row.ends_at).slice(0,16):''})}
async function saveRollout(){if(!rolloutFeature.value)return;const payload={rollout_type:rollout.rollout_type,percentage:Number(rollout.percentage),organization_ids:rollout.organizationText.split(/[,，\s]+/).filter(Boolean).map(Number),device_ids:rollout.deviceText.split(/[,，\s]+/).filter(Boolean),minimum_version:rollout.minimum_version,starts_at:rollout.starts_at||null,ends_at:rollout.ends_at||null,status:rollout.status};try{await platformApi.saveRollout(rolloutFeature.value,editingRollout.value,payload);notice.value=`灰度规则已${editingRollout.value?'更新':'创建'}，影响范围将在 Bootstrap 中重新计算。`;await selectFeature()}catch(e:any){error.value=e.message}}
async function removeRollout(row:any){if(!window.confirm('删除灰度规则后，未被套餐或覆盖控制的功能将回退默认值。确认删除吗？'))return;try{await platformApi.deleteRollout(rolloutFeature.value,row.id);await selectFeature();notice.value='灰度规则已删除并写入审计。'}catch(e:any){error.value=e.message}}
onMounted(load)
</script>
<template><div class="page-stack"><section class="panel"><header class="panel-head"><div><span class="eyebrow">FEATURE GOVERNANCE</span><h2>功能中心</h2><p>维护功能定义、Schema、最低版本、状态和默认值；平台停用拥有最高优先级。</p></div><button class="primary" @click="edit()">新建功能</button></header><div v-if="notice" class="success-banner">{{notice}}</div><div v-if="error" class="form-error">{{error}}</div><form v-if="show" class="feature-form feature-editor" @submit.prevent="saveFeature"><label>功能代码<input v-model="form.feature_code" pattern="[a-z][a-z0-9_]{2,79}" required></label><label>功能名称<input v-model="form.feature_name" required></label><label>分类<input v-model="form.category" required></label><label>使用端<select v-model="form.client_type"><option value="all">全部</option><option value="platform_admin">平台后台</option><option value="enterprise_admin">企业后台</option><option value="windows_client">Windows 客户端</option><option value="api">API</option></select></label><label>最低版本<input v-model="form.minimum_client_version" placeholder="例如 2.2.0"></label><label>发布状态<select v-model="form.status"><option value="internal">内部</option><option value="beta">测试</option><option value="enabled">启用</option><option value="disabled">停用</option><option value="deprecated">废弃</option></select></label><label class="wide">描述<textarea v-model="form.description" rows="2"></textarea></label><label class="wide">配置 Schema JSON<textarea v-model="form.schemaText" rows="6" spellcheck="false"></textarea></label><label class="checkbox-label"><input v-model="form.default_enabled" type="checkbox"> 默认启用</label><div class="form-actions"><button type="button" @click="show=false">取消</button><button class="primary" :disabled="saving">{{saving?'保存中…':editingId?'保存修改':'创建功能'}}</button></div></form><div v-if="loading" class="skeleton-table"><i v-for="n in 6" class="skeleton"></i></div><div v-else-if="!rows.length" class="empty-state"><b>还没有功能定义</b><p>创建首个功能后可配置套餐、企业、设备与角色权限。</p></div><div v-else class="responsive-table"><table><thead><tr><th>功能</th><th>分类/使用端</th><th>状态</th><th>默认</th><th>最低版本</th><th>Schema</th><th>操作</th></tr></thead><tbody><tr v-for="x in rows"><td><b>{{x.feature_name}}</b><small>{{x.feature_code}}</small></td><td>{{x.category}}<small>{{x.client_type}}</small></td><td><span :class="['feature-status',x.status]">{{x.status}}</span></td><td>{{x.default_enabled?'启用':'关闭'}}</td><td>{{x.minimum_client_version||'无限制'}}</td><td><code>{{Object.keys(x.config_schema||{}).length}} 个字段</code></td><td><button class="text-button" @click="edit(x)">编辑 / 废弃</button></td></tr></tbody></table></div></section><section class="panel"><header class="panel-head"><div><h3>灰度发布</h3><p>支持比例、企业、设备、内部和全量发布；时间范围、版本与目标列表同时生效。</p></div></header><div class="toolbar"><select v-model="rolloutFeature" @change="selectFeature"><option value="">选择目标功能</option><option v-for="x in rows" :value="String(x.id)">{{x.feature_name}} · {{x.feature_code}}</option></select></div><div v-if="rolloutFeature" class="rollout-editor"><label>发布范围<select v-model="rollout.rollout_type"><option value="percentage">按比例</option><option value="organizations">按企业</option><option value="devices">按设备</option><option value="internal">内部</option><option value="all">全部</option></select></label><label>灰度比例<input v-model.number="rollout.percentage" type="number" min="0" max="100" :disabled="rollout.rollout_type!=='percentage'"></label><label>最低版本<input v-model="rollout.minimum_version"></label><label>状态<select v-model="rollout.status"><option value="active">生效</option><option value="paused">暂停</option><option value="ended">结束</option></select></label><label>开始时间<input v-model="rollout.starts_at" type="datetime-local"></label><label>结束时间<input v-model="rollout.ends_at" type="datetime-local"></label><label class="wide">企业 ID<input v-model="rollout.organizationText" :disabled="!['organizations','internal'].includes(rollout.rollout_type)" placeholder="用逗号分隔"></label><label class="wide">设备 ID<input v-model="rollout.deviceText" :disabled="!['devices','internal'].includes(rollout.rollout_type)" placeholder="用逗号分隔"></label><footer><button v-if="editingRollout" @click="editingRollout=null;Object.assign(rollout,emptyRollout())">取消编辑</button><button class="primary" @click="saveRollout">{{editingRollout?'保存灰度规则':'创建灰度规则'}}</button></footer></div><div v-if="rolloutFeature&&!rollouts.length" class="empty-state compact"><b>当前功能没有灰度规则</b><p>如果套餐或覆盖也未配置，将使用功能默认值。</p></div><div class="rollout-list"><article v-for="x in rollouts"><div><b>{{x.rollout_type==='percentage'?`${x.percentage}% 灰度`:x.rollout_type}}</b><small>{{x.starts_at?.slice(0,16)||'立即'}} → {{x.ends_at?.slice(0,16)||'长期'}}</small></div><span>企业 {{x.organization_ids.length}} · 设备 {{x.device_ids.length}} · 最低版本 {{x.minimum_version||'无限制'}}</span><span :class="['source-chip',x.status==='active'?'enabled':'default']">{{x.status}}</span><div><button class="text-button" @click="editRollout(x)">编辑</button><button class="danger-text" @click="removeRollout(x)">删除</button></div></article></div></section></div></template>
